import{_ as t,o as a,c as o,ae as n}from"./chunks/framework.BvHJbMD4.js";const d=JSON.parse('{"title":"Research: Corruption of FPÖ and ÖVP (International Perspectives)","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/korruption-oevp-fpoe.md","filePath":"en/recherche/korruption-oevp-fpoe.md"}'),r={name:"en/recherche/korruption-oevp-fpoe.md"};function i(s,e,l,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="research-corruption-of-fpo-and-ovp-international-perspectives" tabindex="-1">Research: Corruption of FPÖ and ÖVP (International Perspectives) <a class="header-anchor" href="#research-corruption-of-fpo-and-ovp-international-perspectives" aria-label="Permalink to &quot;Research: Corruption of FPÖ and ÖVP (International Perspectives)&quot;">​</a></h1><p><strong>The erosion of trust – How political scandals in Austria are viewed globally.</strong></p><p>The political landscape of Austria has been shaken in recent years by a series of corruption allegations and scandals that have also attracted international attention. In our mockumentary, we look at the role of the two major governing parties, FPÖ and ÖVP, and how their actions affect the country&#39;s reputation.</p><hr><h2 id="international-perception" tabindex="-1">International Perception <a class="header-anchor" href="#international-perception" aria-label="Permalink to &quot;International Perception&quot;">​</a></h2><p>Organizations like <strong>Transparency International</strong> and the <strong>GRECO</strong> (Group of States against Corruption) of the Council of Europe have repeatedly criticized the lack of transparency in party financing and the proximity between politics and business in Austria.</p><h3 id="key-points" tabindex="-1">Key Points: <a class="header-anchor" href="#key-points" aria-label="Permalink to &quot;Key Points:&quot;">​</a></h3><ul><li><strong>Ibiza Affair:</strong> Viewed worldwide as a classic example of political hubris and the sale of state structures.</li><li><strong>The &quot;Kurz System&quot;:</strong> Often described in international media as &quot;Orbanization&quot; of the Austrian media landscape.</li><li><strong>Horten Legacy:</strong> The case of Heidi Horten&#39;s donations is cited internationally as a prime example of &quot;Legalized Corruption&quot; – where huge sums flow legally but opaque to the public.</li></ul><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In our film, we use the international view as a corrective. While national actors attempt to downplay the scandals as &quot;common practice,&quot; the international perspective reveals the systemic failure.</p><ul><li><strong>Satirical Motif:</strong> We show a fictional &quot;International Commission for the Preservation of Political Decency&quot; that despairs over the creative interpretations of Austrian laws.</li></ul><hr><p><em>Sources: Corruption Perceptions Index (Transparency International), GRECO reports on Austria.</em></p>',14)])])}const f=t(r,[["render",i]]);export{d as __pageData,f as default};
